INSERT INTO dump_descriptions (base_key, description) VALUES ('haz5p4x2_p', 'Sets Hazard 5 enemy-count modifier to 3× for all party sizes, with 3.4× enemy damage and 1.5× resistance.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('haz6x2', 'Adds the Hazard 6 “Hurtme” profile with enemy-count modifiers of 1.9×–3.3×, enemy damage of 3.3×–4.1×, and 1.4×–1.75× resistance by party size; resupply costs 40 Nitra instead of 80.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
